<template>
  <q-card class="width-600">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold">{{ $t('add_supplier') }}</span>
      </q-toolbar-title>

      <q-btn flat round dense icon="close" v-close-popup @click="toggleCreatedDialog" />
    </q-toolbar>

    <q-form ref="formEl">
      <q-card-section class="q-pt-md q-pb-md q-px-md" style="max-height: 70vh; overflow-y: auto;">
        <div class="row q-col-gutter-md">
          <!-- Supplier Group -->
          <div class="col-12">
            <q-select
              v-model="newSupplier.group"
              :label="$t('supplierGroup')"
              outlined
              dense
              hide-bottom-space
              :options="supplierOptionList"
              map-options
              emit-value
              :error="!!newSupplier.sppGroupError"
              :error-message="newSupplier.sppGroupError"
            />
          </div>

          <!-- Supplier Name -->
          <div class="col-12">
            <q-input
              v-model="newSupplier.orgName"
              :label="$t('supplier_name')"
              outlined
              dense
              hide-bottom-space
              :error="!!newSupplier.sppNameError"
              :error-message="newSupplier.sppNameError"
            />
          </div>

          <!-- Responder First Name -->
          <div class="col-12 col-sm-6 q-pr-sm">
            <q-input
              v-model="newSupplier.firstName"
              :label="$t('supplier_responder_first_name')"
              outlined
              dense
              hide-bottom-space
              :error="!!newSupplier.responderFirstNameError"
              :error-message="newSupplier.responderFirstNameError"
            />
          </div>

          <!-- Responder Last Name -->
          <div class="col-12 col-sm-6 q-pl-sm">
            <q-input
              v-model="newSupplier.name"
              :label="$t('supplier_responder_last_name')"
              outlined
              dense
              hide-bottom-space
              :error="!!newSupplier.responderNameError"
              :error-message="newSupplier.responderNameError"
            />
          </div>

          <!-- Responder Email -->
          <div class="col-12">
            <q-input
              v-model="newSupplier.email"
              :label="$t('supplier_responder_email')"
              outlined
              dense
              hide-bottom-space
              type="email"
              :error="!!newSupplier.responderEmailError"
              :error-message="newSupplier.responderEmailError"
            />
          </div>

          <!-- Additional Fields -->
          <template v-for="(field, index) in additionalFields" :key="index">
            <div class="col-12">
              <MagicLinkField
                :meta_field="field"
                :readonly="field.readonly"
                v-model="magicLinkAdditionalData[index]"
              />
            </div>
          </template>
        </div>
      </q-card-section>
    </q-form>

    <q-separator class="q-mt-md" />

    <q-card-actions align="right" class="q-pa-md">
      <f-btn :label="$t('cancel')" appearance="cancel" v-close-popup @click="toggleCreatedDialog" />
      <f-btn
        @click="save"
        :label="$t('save')"
      />
    </q-card-actions>
  </q-card>
</template>

<script>
import { storeToRefs } from 'pinia';
import { ApiExceptions } from 'src/exceptions';
import { magicLinkApiService } from 'src/services';
import { useDashboardSupplierStore } from 'src/supplier/store';
import { notify } from 'src/components/notifications/notify';
import MagicLinkField from 'src/supplier/components/dynamic/form/MagicLinkField.vue';

export default {
  name: 'SupplierCreate',
  components: {
    MagicLinkField
  },
  setup() {
    const dashboardSupplierStore = useDashboardSupplierStore();
    const { loading, additionalFields, supplierOptionList } = storeToRefs(dashboardSupplierStore);
    const { toggleCreatedDialog, getSupplierData } = dashboardSupplierStore;

    return {
      loading,
      additionalFields,
      supplierOptionList,
      dashboardSupplierStore,
      getSupplierData,
      toggleCreatedDialog,
    };
  },
  data() {
    return {
      formEl: null,
      newSupplier: {
        group: '',
        orgName: '',
        firstName: '',
        name: '',
        email: '',
        sppGroupError: '',
        sppNameError: '',
        responderFirstNameError: '',
        responderNameError: '',
        responderEmailError: '',
      },
      magicLinkAdditionalData: {}
    };
  },
  methods: {
    isValidEmail(email) {
      const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      return re.test(email);
    },

    async validateFiled() {
      let error = false;
      //reset all error messages
      this.newSupplier.sppGroupError = '';
      this.newSupplier.sppNameError = '';
      this.newSupplier.responderFirstNameError = '';
      this.newSupplier.responderNameError = '';
      this.newSupplier.responderEmailError = '';

      if (this.newSupplier.group === '') {
        this.newSupplier.sppGroupError = 'Supplier group is required';
        error = true;
      }
      if (this.newSupplier.orgName === '') {
        this.newSupplier.sppNameError = 'Supplier name is required';
        error = true;
      }
      if (!this.newSupplier.firstName) {
        this.newSupplier.responderFirstNameError = 'Responder first name is required';
        error = true;
      }
      if (this.newSupplier.name === '') {
        this.newSupplier.responderNameError = 'Responder last name is required';
        error = true;
      }
      if (this.newSupplier.email === '') {
        this.newSupplier.responderEmailError = 'Responder email is required';
        error = true;
      }
      if (!this.isValidEmail(this.newSupplier.email)) {
        this.newSupplier.responderEmailError = 'Responder email is invalid';
        error = true;
      }
      if(error == false){
        //validate additional fields and get result
        error = !await this.$refs.formEl.validate();
      } else {
        //already failed the validation so just need to validate error additional fields
        await this.$refs.formEl.validate();
      }
      return error;
    },

    async save() {
      let error = await this.validateFiled();
      //if error is false then it means validation is failed
      if (error) {
        return;
      }

      this.loading = true;

      const data = {
        supplier_type: this.newSupplier.group,
        org_name: this.newSupplier.orgName,
        responder_first_name: this.newSupplier.firstName,
        responder_name: this.newSupplier.name,
        responder_email: this.newSupplier.email,
        additional_data: this.magicLinkAdditionalData
      };

      await magicLinkApiService.sendMagicLink(data)
      .then((res) => {
        if (!res.success) {
          notify.error(res?.message);
        } else {
          notify.success(this.$t('send_success'));
          this.toggleCreatedDialog();
        }
      })
      .catch((e) => {
        const msg = ApiExceptions.getErrorMessage(e);
        notify.error(msg);
      })
      .finally(() => {
        this.getSupplierData().finally(() => {
          this.loading = false;
        });
      })
    }
  }
};
</script>