<template>
  <q-input
    outlined
    dense
    v-model="filter.date_added"
    @update:model-value="fetchData"
    :clearable="true"
    class="q-mr-sm"
    style="width: 227px; height: 40px"
  >
    <template v-slot:append>
      <q-icon name="event" class="cursor-pointer">
        <q-popup-proxy cover transition-show="scale" transition-hide="scale">
          <q-date
            @update:model-value="fetchData"
            v-model="filter.date_added"
            mask="YYYY-MM-DD"
          >
            <div class="row items-center justify-end">
              <q-btn v-close-popup label="Close" color="primary" flat />
            </div>
          </q-date>
        </q-popup-proxy>
      </q-icon>
    </template>
  </q-input>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useDashboardSupplierStore } from 'src/supplier/store';
export default defineComponent({
  mixins: [],
  props: {},
  mounted() {
    // document.addEventListener('reset_filters', this.resetFilters);
  },
  unmounted: function () {
    // document.removeEventListener('reset_filters', this.resetFilters);
  },

  methods: {
    fetchData(value: any) {
      this.filter.date_added = value;
      this.resetPagination();
      this.getSupplierData();
    },
  },
  setup() {
    const date = ref();
    const store = storeToRefs(useDashboardSupplierStore());
    const { getSupplierData, resetPagination } = useDashboardSupplierStore();
    const { filter } = store;
    return {
      resetPagination,
      getSupplierData,
      filter,
      date,
    };
  },
});
</script>
