<template>
  <q-select
    outlined
    class="q-mr-sm"
    style="width: 227px; height: 40px"
    clearable
    dense
    v-model="filter.supplier_group"
    :options="supplierOptionList"
    :label="$t('supplier_groups')"
    @update:model-value="fetchData"
  >
    <template v-slot:selected-item="scope">
      <div>{{ scope.opt.label }}</div>
    </template>
  </q-select>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { supplierGroupOptions } from 'src/supplier/constant';
import { useDashboardSupplierStore } from 'src/supplier/store';
import { storeToRefs } from 'pinia';
export default defineComponent({
  mixins: [],
  props: {},
  mounted() {
    // document.addEventListener('reset_filters', this.resetFilters);
  },
  unmounted: function () {
    // document.removeEventListener('reset_filters', this.resetFilters);
  },

  methods: {
    fetchData() {
      this.resetPagination();
      this.getSupplierData();
    },
  },

  setup() {
    const groups = supplierGroupOptions;
    const selected_group = ref();
    const store = storeToRefs(useDashboardSupplierStore());
    const { getSupplierData, resetPagination } = useDashboardSupplierStore();
    const { filter, supplierOptionList } = store;
    return {
      groups,
      selected_group,
      filter,
      getSupplierData,
      resetPagination,
      supplierOptionList,
    };
  },
});
</script>
<style lang="scss">
.select-box.doc-type-select {
  max-width: 260px;
}
</style>
