<template>
  <SubHeader name='supplier_dashboard' :label="$t('SUPPLIER_MANAGEMENT')" :show_expiry_alert="true" :onSearch="false" />

  <div class="dashboard-container dashboard-text-color dashboard-main">
    <DashboardHeader/>
    <q-separator class="seperator" />
    <div class="full-width dashboard-list-area q-my-lg" style="overflow-x: auto;">
      <DocBitsTable
        :rows="tableRows"
        :columns="v2TableColumns"
        row-key="supplier_lookup_record_id"
        table-id="supplier_table"
        :loading="loading"
        :features="v2TableFeatures"
        :row-actions="v2RowActions"
        :pagination="v2PaginationState"
        :rows-per-page-options="[10, 20, 25, 50]"
        pagination-label="supplier_per_page"
        :pagination-settings-key="pagination_settings_key"
        no-data-label="no_record_found"
        :column-order="v2ColumnOrder"
        table-class="scroll-height-100vh-265px"
        @update:sorting="handleV2Sort"
        @update:pagination="handleV2Pagination"
        @column-reorder="handleV2ColumnReorder"
        @row-click="handleV2RowClick"
        @row-action="handleV2RowAction"
      >
        <!-- Status Column - Badge -->
        <template #body-cell-status="{ row }">
          <q-badge align="middle" :class="getStatusClass(row.status)">
            <span class="dashboard-status-text pa-2">{{ $t(row.status) }}</span>
          </q-badge>
          <q-tooltip>
            {{ $t(row.status) }}
          </q-tooltip>
        </template>

        <!-- Supplier Type Column -->
        <template #body-cell-supplier_type="{ row }">
          <div class="text-item">
            {{ getSupplierGroupLabelByValue(row.supplier_type) }}
            <q-tooltip v-if="getSupplierGroupLabelByValue(row.supplier_type)">
              {{ getSupplierGroupLabelByValue(row.supplier_type) }}
            </q-tooltip>
          </div>
        </template>

        <!-- Created On Column -->
        <template #body-cell-created_on="{ row }">
          {{ formatDateAccordingToPreference(row.created_on) }}
        </template>

        <!-- Last Modified On Column -->
        <template #body-cell-last_modified_on="{ row }">
          {{ formatDateAccordingToPreference(row.last_modified_on) }}
        </template>
      </DocBitsTable>
    </div>
  </div>

  <!-- Magic Link Dialog -->
  <q-dialog v-model="dialogVisible" @before-hide="hideMagicLinkDialog">
    <q-card class="card">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold">{{ $t('magic_link') }}</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="row">
        <q-select
          v-model="sppGroup"
          :label="$t('supplierGroup')"
          outlined
          dense
          class="col-12 card-padding"
          :options="supplierOptionList"
          map-options
          emit-value
        >
          <template v-slot:append>
            <q-icon v-if="sppGroupError" color="red" name="error">
              <q-tooltip>{{ sppGroupError }}</q-tooltip>
            </q-icon>
          </template>
        </q-select>
        <q-input
          v-model="sppOrgName"
          :label="$t('supplier_name')"
          outlined
          dense
          class="col-12 card-padding"
        >
          <template v-slot:append>
            <q-icon v-if="sppNameError" color="red" name="error">
              <q-tooltip>{{ sppNameError }}</q-tooltip>
            </q-icon>
          </template>
        </q-input>
        <q-input
          v-model="responderFirstName"
          :label="$t('supplier_responder_first_name')"
          outlined
          dense
          class="col-12 card-padding"
        >
          <template v-slot:append>
            <q-icon v-if="responderFirstNameError" color="red" name="error">
              <q-tooltip>{{ responderFirstNameError }}</q-tooltip>
            </q-icon>
          </template>
        </q-input>
        <q-input
          v-model="responderName"
          :label="$t('supplier_responder_last_name')"
          outlined
          dense
          class="col-12 card-padding"
        >
          <template v-slot:append>
            <q-icon v-if="responderNameError" color="red" name="error">
              <q-tooltip>{{ responderNameError }}</q-tooltip>
            </q-icon>
          </template>
        </q-input>
        <q-input
          v-model="responderEmail"
          :label="$t('supplier_responder_email')"
          outlined
          dense
          class="col-12 card-padding"
        >
          <template v-slot:append>
            <q-icon v-if="responderEmailError" color="red" name="error">
              <q-tooltip>{{ responderEmailError }}</q-tooltip>
            </q-icon>
          </template>
        </q-input>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn :label="$t('cancel')" appearance="cancel" v-close-popup />
        <f-btn
          @click="sendMagicLink"
          class="q-mr-sm"
          :label="$t('send')"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <q-inner-loading :showing="loading" style="z-index: 10000;">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
// @ts-nocheck
import { storeToRefs } from 'pinia';
import { ref, defineComponent } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions';
import dragDropColumn from 'src/mixins/dragDropColumn';
import { useDashboardSupplierStore } from '../store/index';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { useSettingStore, useUserFontSizeStore } from 'src/store/main';
import DashboardHeader from '../components/dashboard/DashboardHeader.vue';
import { supplier_dashboard_setting, supplier_dashboard_columns } from 'src/constants';
import { magicLinkApiService, supplierDataApiService, listOfValuesApiService } from 'src/services';
import { getSavedOrderByColumns, makeOrderByJsonForApi, removeSortOrderFromStorage } from 'src/utils/ms_utlis';
import {
  supplier_portal_with_layout_setting,
  supplier_portal_additional_fields_preference,
  supplier_portal_additional_fields,
  supplier_statuses
} from 'src/constants';
import dateUtils from 'src/utils/date';
import { docFieldsApiService } from 'src/services';
import { DocBitsTable } from 'src/components/Table';
import { notify } from 'src/components/notifications/notify';
import generateSavedColumns from 'src/utils/generateSavedColumns';
import { getSavedPaginationSize } from 'src/components/Table/PaginationSettings.vue';
import type {
  RowActionItem,
  SortEventPayload,
  PaginationChangePayload,
  RowActionPayload,
  RowClickPayload,
  UnifiedTableColumn,
} from 'src/components/Table';

export default defineComponent({
  mixins: [dragDropColumn, generateSavedColumns, dateUtils],
  props: {
    type_name: {
      type: String,
      reqired: true,
      default: 'supplier',
    },
  },
  components: {
    SubHeader,
    DashboardHeader,
    DocBitsTable,
  },
  data() {
    return {
      pagination_settings_key: 'SUPPLIER_PAGINATION_SIZE',
      selectedIndex: 0,
      columnListPreferenc: [] as any,
      enableSaveColumnOrderBtn: false,
      supplier_dashboard_setting,
      dialogVisible: false,
      sppGroupError: '',
      sppNameError: '',
      responderFirstNameError: '',
      responderNameError: '',
      responderEmailError: '',
      show_table_loader: false,
      supplier_dashboard_columns,
      dialogLoading: false,
      supplierGroupLOVKey: '',
    };
  },
  setup() {
    const dashboard_supplier_store = useDashboardSupplierStore();
    const {
      current_supplier,
      pending_approval_supplier,
      display_data,
      loading,
      paginationCount,
      table_columns,
      supplier_status,
      sortby_data_types,
      created_dialog,
      pagination,
      additionalFields,
      supplierOptionList,
      supplierStatusList
    } = storeToRefs(dashboard_supplier_store);
    const {
      getSupplierData,
      toggleCreatedDialog,
      resetPagination,
      resetFilter,
      getSavedColumns,
      getStatusByValue
    } = dashboard_supplier_store;

    const user_font_size_store = useUserFontSizeStore();
    const { initFontSize } = user_font_size_store;

    const tableColumns = ref();
    tableColumns.value = Object.values(JSON.parse(JSON.stringify(table_columns.value))).map((column: any) => {
      return {
        name: column.name,
        required: true,
        label: column.translation_key,
        field: column.field,
        actions: column.actions,
      } as dynamicObj;
    });
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { startSettingsFetch, updateSetting, datePattern } = settings_store;

    return {
      getSavedColumns,
      getStatusByValue,
      user_settings,
      startSettingsFetch,
      getSupplierData,
      additionalFields,
      supplierOptionList,
      data_type: ref('supplier'),
      sortby_data_types,
      removeSortOrderFromStorage,
      resetFilter,
      current_supplier,
      dashboard_supplier_store,
      display_data,
      filter_data: ref({} as dynamicObj),
      pending_approval_supplier,
      loading,
      table_columns,
      loading_settings,
      paginationCount,
      resetPagination,
      update_columns: ref([] as dynamicObj[]),
      request_params: ref({} as any),
      existMagicLinkData: ref({} as dynamicObj),
      startfrom: ref(0),
      tableColumns,
      total_records: ref(0),
      offset: ref(0),
      filter_data_json_str: ref(''),
      supplier_status,
      sppGroup: ref(''),
      sppOrgName: ref(''),
      responderFirstName: ref(''),
      responderName: ref(''),
      responderEmail: ref(''),
      pagination,
      magic_link_selected_row: ref({} as dynamicObj),
      initFontSize,
      supplier_portal_with_layout_setting,
      supplier_portal_additional_fields_preference,
      supplier_portal_additional_fields,
      updateSetting,
      datePattern,
      statusList: ref({} as any),
      supplierStatusList,
      supplier_statuses,
    };
  },
  computed: {
    /**
     * Table rows from store display_data
     */
    tableRows(): dynamicObj[] {
      return Object.values(this.display_data);
    },

    /**
     * V2 Table: Transform table_columns to UnifiedTableColumn format
     */
    v2TableColumns(): UnifiedTableColumn[] {
      return this.tableColumns.map((col: any) => {
        const name = col.field || col.name;
        return {
          name,
          label: this.$t(col.label || col.translation_key || col.name),
          field: name,
          sortable: col.actions === true,
          align: 'left' as const,
          // Prevent truncation on status column
          classes: name === 'status' ? 'no-truncate' : undefined,
        };
      });
    },

    /**
     * V2 Table: Column order for persisted column reordering
     */
    v2ColumnOrder(): string[] {
      return this.tableColumns.map((col: any) => col.field || col.name);
    },

    /**
     * V2 Table: Feature configuration
     */
    v2TableFeatures() {
      return {
        sorting: true,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: true,
        columnReorder: true,
        stickyFirstColumn: true,
        stickyLastColumn: true,
      };
    },

    /**
     * V2 Table: Pagination state (includes sort info)
     */
    v2PaginationState() {
      let sortBy = null;
      let descending = false;

      if (this.sortby_data_types[this.type_name]?.orderByMap) {
        const orderByMap = this.sortby_data_types[this.type_name].orderByMap;
        if (orderByMap.size > 0) {
          const firstEntry = orderByMap.entries().next().value;
          if (firstEntry) {
            sortBy = firstEntry[0];
            descending = firstEntry[1] === 'desc';
          }
        }
      }

      return {
        sortBy,
        descending,
        page: this.pagination.current_page,
        rowsPerPage: this.pagination.page_size,
        rowsNumber: this.paginationCount || 0,
      };
    },

    /**
     * V2 Table: Row actions configuration
     */
    v2RowActions(): RowActionItem[] {
      return [
        { key: 'magic_link', label: 'magic_link', icon: 'link', color: 'primary' },
      ];
    },
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == true && oldVal == false) {
          return;
        }
        this.loadAdditionalFields();
        this.loadSupplierStatusOptions();
      },
    },
  },
  mounted() {
    this.removeSortOrderFromStorage('supplier');
    this.init();
    this.prepareTableColumns();
    this.initFontSize();
    this.initDragDropColumns('supplier_table', 'label');
    document.addEventListener('supplier_table-column-drop', this.onDropColumns);
    document.addEventListener('sup_search', this.searchEvent);
    document.addEventListener('supplier_refresh_data', this.refreshFilters);
    document.addEventListener('sup_pending', this.handleSupPending);
    document.addEventListener('columnsUpdated', this.refreshColumns);
    this.loadAdditionalFields();
    this.loadSupplierStatusOptions();
  },
  unmounted() {
    document.removeEventListener('sup_search', this.searchEvent);
    document.removeEventListener('supplier_refresh_data', this.refreshFilters);
    document.removeEventListener('columnsUpdated', this.refreshColumns);
    document.removeEventListener('sup_pending', this.handleSupPending);
    document.removeEventListener('supplier_table-column-drop', this.onDropColumns);
  },
  methods: {
    // ========== V2 Table Event Handlers ==========
    async handleV2Sort(payload: SortEventPayload) {
      // Update store sorting
      if (!this.sortby_data_types[this.type_name]) {
        this.sortby_data_types[this.type_name] = { orderByMap: new Map() };
      }
      this.sortby_data_types[this.type_name].orderByMap.clear();
      this.sortby_data_types[this.type_name].orderByMap.set(payload.column, payload.direction);

      await this.getDataServer(true);
    },

    async handleV2Pagination(payload: PaginationChangePayload) {
      this.pagination.current_page = payload.page;
      this.pagination.page_size = payload.rowsPerPage;
      await this.getDataServer(true);
    },

    handleV2RowClick(payload: RowClickPayload) {
      this.navigate(payload.row);
    },

    async handleV2ColumnReorder(columnNames: string[]) {
      const columnsToSave = columnNames.map((fieldName, index) => {
        const col = this.tableColumns.find((c: any) => (c.field || c.name) === fieldName);
        if (col) {
          return {
            ...col,
            order: index,
          };
        }
        return null;
      }).filter(Boolean);

      // Update local state
      this.tableColumns = columnsToSave;

      // Save to backend
      await this.saveSortedColumns(columnsToSave);
    },

    handleV2RowAction(payload: RowActionPayload) {
      if (payload.action === 'magic_link') {
        this.openMagicLink(payload.row);
      }
    },

    handleSupPending() {
      this.getDataServer(true);
    },
    // ========== End V2 Table Event Handlers ==========

    refreshColumns(e: any) {
      if (e.detail) {
        this.tableColumns = e.detail.visible_columns;
      }
    },

    async openMagicLink(data: any) {
      try {
        this.dialogLoading = true;
        this.dialogVisible = true;
        this.sppGroup = data.supplier_type;
        this.sppOrgName = data.supplier_name;
        this.responderFirstName = data.responder_first_name;
        this.responderName = data.responder_name;
        this.responderEmail = data.responder_email;
        this.magic_link_selected_row = data;
        this.sppGroupError = '';
        this.sppNameError = '';
        this.responderFirstNameError = '';
        this.responderNameError = '';
        this.responderEmailError = '';
        const response = await supplierDataApiService.getOrgSupplierDetails(data.supplier_lookup_record_id, data.supplier_as_org_id);
        if (response.success) {
          Object.values(this.additionalFields).forEach((field: dynamicObj) => {
            if (response.data[field.field_name]) {
              this.existMagicLinkData[field.field_name] = response.data[field.field_name];
            }
          });
        }
        this.dialogLoading = false;
      } catch (error) {
        logInfo(error, 'error');
      }
    },

    hideMagicLinkDialog() {
      this.sppGroup = '';
      this.sppOrgName = '';
      this.responderFirstName = '';
      this.responderName = '';
      this.responderEmail = '';
      this.existMagicLinkData = {};
    },

    isValidEmail(email: string) {
      const re = /\S+@\S+\.\S+/;
      return re.test(email);
    },

    getStatusClass(status: any) {
      let status_class = 'bg-grey';
      const status_exists = this.statusList.hasOwnProperty(status);
      if (status_exists) {
        status_class = this.statusList[status]['class'];
      }
      status_class += ' dashboard-status-badge';
      return status_class;
    },

    prepareStatusList() {
      this.statusList['pending_registration'] = { value: 'pending_registration', class: 'bg-amber-7' };
      this.statusList['pending_approval'] = { value: 'pending_approval', class: 'bg-blue-6' };
      this.statusList['pending_ap_approval'] = { value: 'pending_ap_approval', class: 'bg-teal-5' };
      this.statusList['pending_supplier_input'] = { value: 'pending_supplier_input', class: 'bg-lime-6' };
      this.statusList['approved'] = { value: 'approved', class: 'bg-light-green-6' };
      this.statusList['rejected'] = { value: 'rejected', class: 'bg-red-13' };
      this.statusList['pending_lt_approval'] = { value: 'pending_lt_approval', class: 'bg-blue-grey-6' };
    },

    validateFiled() {
      let error = false;

      if (!this.sppGroup) {
        this.sppGroupError = 'Supplier group is required';
        error = true;
      }
      if (!this.sppOrgName) {
        this.sppNameError = 'Supplier name is required';
        error = true;
      }
      if (!this.responderFirstName) {
        this.responderFirstNameError = 'Responder first name is required';
        error = true;
      }
      if (!this.responderName) {
        this.responderNameError = 'Responder last name is required';
        error = true;
      }
      if (!this.responderEmail) {
        this.responderEmailError = 'Responder email is required';
        error = true;
      }
      if (!this.isValidEmail(this.responderEmail)) {
        this.responderEmailError = 'Responder email is invalid';
        error = true;
      }

      return error;
    },

    async sendMagicLink() {
      try {
        if (this.validateFiled()) {
          return;
        }
        this.dialogVisible = false;
        this.loading = true;
        const data = {
          org_name: this.sppOrgName,
          supplier_type: this.sppGroup,
          responder_first_name: this.responderFirstName,
          responder_name: this.responderName,
          responder_email: this.responderEmail,
          erp_supplier_id: this.magic_link_selected_row.erp_supplier_id,
          supplier_lookup_record_id: this.magic_link_selected_row.supplier_lookup_record_id,
          existing_id: this.magic_link_selected_row.existing_id,
          additional_data: this.existMagicLinkData,
        };
        const res = await magicLinkApiService.sendMagicLink(data);
        if (!res.success) {
          notify.error(res?.message);
        } else {
          await this.getDataServer(true);
          notify.success(this.$t('send_success'));
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      } finally {
        this.loading = false;
      }
    },

    async loadAdditionalFields() {
      const preference = this.user_settings[this.supplier_portal_additional_fields_preference];
      if (preference) {
        await this.getAdditionalFields();
      } else if (this.loading_settings == false) {
        await this.loadSupplierGroupOptions();
      }
    },

    async loadSupplierGroupOptions() {
      try {
        const data = {
          doc_type: 'SUPPLIER_M3',
        };
        let fields = [] as dynamicObj[];
        const response = await docFieldsApiService.getFieldSettingsByType(data);
        if (response.field_setting.length > 0) {
          fields = response.field_setting[0].rows.map((field: Array<dynamicObj>) => {
            return field[0];
          });
        }
        const supplierGroup = fields.find((f: dynamicObj) => f.field_name === 'supplier_group');
        if (supplierGroup) {
          this.supplierGroupLOVKey = supplierGroup.list_of_values;
          await this.mapListOfValue([supplierGroup.list_of_values]);
        }
      } catch (error) {
        logError(error);
      }
    },

    async getAdditionalFields() {
      try {
        const data = {
          doc_type: 'SUPPLIER_M3',
        };
        let additionalFieldsSetting = this.user_settings[this.supplier_portal_additional_fields];
        let fields = [] as dynamicObj[];
        if (additionalFieldsSetting) {
          additionalFieldsSetting = JSON.parse(additionalFieldsSetting);
        } else {
          return;
        }
        const response = await docFieldsApiService.getFieldSettingsByType(data);
        if (response.field_setting.length > 0) {
          fields = response.field_setting[0].rows.map((field: Array<dynamicObj>) => {
            return field[0];
          });
        }
        const listOfValues = [] as string[];
        const supplierGroup = fields.find((f: dynamicObj) => f.field_name === 'supplier_group');
        let preparedAdditionalFields = additionalFieldsSetting.map((field: dynamicObj) => {
          const fieldData = fields.find((f: dynamicObj) => f.field_name === field);
          if (fieldData && fieldData.list_of_values) {
            listOfValues.push(fieldData.list_of_values);
          }
          const key = fieldData?.field_name;
          return { [key]: fieldData };
        }) as dynamicObj[];
        preparedAdditionalFields = Object.assign({}, ...preparedAdditionalFields);
        this.additionalFields = preparedAdditionalFields;
        if (listOfValues.length > 0) {
          if (supplierGroup) {
            this.supplierGroupLOVKey = supplierGroup.list_of_values;
            await this.mapListOfValue([...listOfValues, supplierGroup.list_of_values]);
          } else {
            await this.mapListOfValue(listOfValues);
          }
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
      }
    },

    async mapListOfValue(listOfValues: string[]) {
      try {
        const response: dynamicObj = await listOfValuesApiService.getMultipleListOfValues(listOfValues.join(','));
        if (response.success) {
          const data = response.data as dynamicObj;
          for (const [key, lov] of Object.entries(data)) {
            const field = Object.values(this.additionalFields).find((f: any) => f?.list_of_values === key);
            if (field) {
              (field as any).options = (lov as any[]).map((obj: dynamicObj) => ({
                label: obj.label ? obj.label[0].translated_value : obj.value,
                value: obj.value,
              }));
            }
          }
          const supplierGroupOpts = data[this.supplierGroupLOVKey];
          if (supplierGroupOpts) {
            this.supplierOptionList = (supplierGroupOpts as any[]).map((obj: dynamicObj) => ({
              label: obj.label ? obj.label[0].translated_value : obj.value,
              value: obj.value,
            }));
          }
        }
      } catch (error) {
        logError(error);
      }
    },

    refreshFilters() {
      this.init();
      this.resetPagination();
      this.resetFilter();
      this.supplier_status = '';
    },

    searchEvent(e: any) {
      if (e.detail.data_type != this.type_name) {
        return;
      }
      this.sortTable();
    },

    async sortTable() {
      try {
        this.loading = true;
        this.filter_data_json_str = this.getSearchJson();
        await this.getDataServer(true);
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
      }
    },

    getSearchJson() {
      let filter_data_json_str = '';
      let filter_data_json = {} as dynamicObj;
      let filters = [] as dynamicObj[];
      if (this.supplier_status) {
        filters.push({
          'field': 'status',
          'operator': 'smart',
          'value': this.supplier_status,
        });
        filter_data_json['filters'] = filters;
        filter_data_json['match_all'] = false;
        filter_data_json_str = JSON.stringify(filter_data_json);
      }
      return filter_data_json_str;
    },

    setRowStyle(row: any) {
      if (row.hasOwnProperty('export_data_fetched') && row['export_data_fetched'] === true) {
        return 'exported-row';
      }
      return 'exported-row';
    },

    async init() {
      try {
        this.loading = true;
        await this.startSettingsFetch();
        this.pagination.page_size = await getSavedPaginationSize(this.pagination_settings_key);
        this.getOrderByColumns();
        await this.getDataServer(true);
        this.prepareStatusList();
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
      }
    },

    async getDataServer(show_table_loader: boolean) {
      try {
        this.loading = true;
        if (show_table_loader) {
          this.show_table_loader = true;
        }
        await this.getSupplierData();
      } catch (err) {
        logError(err);
      } finally {
        this.loading = false;
        this.show_table_loader = false;
      }
    },

    async paginationItemClicked() {
      try {
        await this.getDataServer(true);
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
      }
    },

    async prepareTableColumns() {
      this.tableColumns = await this.getSavedColumns();
    },

    onDropColumns() {
      this.saveSortedColumns(this.tableColumns);
    },

    async saveSortedColumns(tableColumns: any) {
      let visibleColumnsSorted = JSON.parse(JSON.stringify(tableColumns));
      let visibleColumnsSortedObject = {} as any;
      visibleColumnsSorted.forEach((column: any, index: number) => {
        visibleColumnsSortedObject[column.field] = {
          name: column.name,
          label: column.label,
          order: index,
          sortable: column.sortable,
          selected: false,
          translation_key: column.translation_key,
          field: column.field
        };
        if (column.doc_type_key) {
          visibleColumnsSortedObject[column.name].doc_type_key = column.doc_type_key;
        }
      });
      await this.updateSetting(this.supplier_dashboard_columns, JSON.stringify(visibleColumnsSortedObject));
    },

    getOrderByColumns() {
      this.sortby_data_types[this.type_name] = {};
      this.sortby_data_types[this.type_name]['orderByMap'] = getSavedOrderByColumns(this.type_name);
    },

    navigate(row: any) {
      const lookupRecordId: string = row.supplier_lookup_record_id ? row.supplier_lookup_record_id : 'supplier_lookup_record_id' as string;
      const supplierAsOrgId: string = row.supplier_as_org_id ? row.supplier_as_org_id : 'supplier_as_org_id' as string;
      this.$router.push(`/supplier/details/${lookupRecordId}/${supplierAsOrgId}`);
    },

    loadSupplierStatusOptions() {
      try {
        const status_list = this.user_settings[this.supplier_statuses];
        if (status_list) {
          this.supplierStatusList = JSON.parse(status_list);
        }
      } catch (error) {
        logError(error);
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
      }
    },

    getSupplierGroupLabelByValue(value: string) {
      const optionIndex = this.supplierOptionList.findIndex((status: { value: string }) => status.value === value);
      if (optionIndex > -1) {
        return this.supplierOptionList[optionIndex].label;
      }
      return '';
    },
  },
});
</script>

