<template>
            
          <!-- <label class="row items-center" >
            {{ meta_field.label ? $t(meta_field.label) : $t(meta_field.translation_key) }}
            <span class="text-red">&nbsp;{{asterisk}}</span>
            <q-icon v-if="meta_field.labelHint" name="info" style="font-size:large;color: orange; padding-bottom: 5px">
              <q-tooltip>{{ $t(meta_field.labelHint) }}</q-tooltip>
            </q-icon>
          </label> -->
          <component
            :is="fieldComponent"
            :meta_field="meta_field"
            :name="props.meta_field.field_name"
            :type="meta_field.field_type === 'group-checkbox' ? 'checkbox' : meta_field.field_type"
            :translationKey="props.translationKey"
            :disable="false"
            :readonly="false"
            :model-value="modelValue"
            :stack-label="false"
            :label="meta_field.label ? $t(meta_field.label) : $t(meta_field.translation_key)"
            @update:model-value="onUpdateValue($event)"
            dense
            outlined
            hide-bottom-space
            reactive-rules
            :label-slot="false"
            :asterisk="asterisk"
            :autogrow="meta_field.field_type === 'textarea' || meta_field.field_type === 'TEXTAREA'"
            :rules="[
            ...(meta_field.is_required ? [ (val: string) => !!val || $t(meta_field.requiredMessageKey ? $t(`${props.translationKey}.error.${meta_field.requiredMessageKey}`) :'field_required')] : []),
            ...(meta_field.field_type === 'email') ? [ (val: string) => emailRule(val) || $t(`${props.translationKey}.error.email_err`)] : [],
            ...meta_field.rules?.map((rule) => {
              return (value: any) => rule.rule(value) || $t(`${props.translationKey}.error.${rule.messageKey}`)
            }) || []
          ]"
          />
        <!-- <template v-if="meta_field.after">
          <q-space />
          <component v-bind="meta_field.after.props" :is="meta_field.after.component" v-html="innerHtml" :onclick="afterClick"/>
        </template> -->
      
  </template>
  <script setup lang="ts">
  import { dynamicObj } from 'pages/assets';
  import { emailRule } from 'src/supplier/utils/validator'
  import { computed, onMounted, watch, ref } from 'vue';
  import { FieldValue, MetaField, MetaKeys } from 'src/supplier/types/meta';
  import InputField from 'src/supplier/components/dynamic/form/InputField.vue';
  import OptionField from 'src/supplier/components/dynamic/form/OptionField.vue';
  import SelectField from 'src/supplier/components/dynamic/form/SelectField.vue';
  import CheckboxField from 'src/supplier/components/dynamic/form/CheckboxField.vue';
  import FileField from 'src/supplier/components/dynamic/form/FileField.vue';
  import { useSupplierLayoutsStore } from 'src/store/main';
  import { storeToRefs } from 'pinia';
  import type { Component } from 'vue';
  type FieldProps = {
    meta_field : any,
    modelValue : FieldValue<dynamicObj, MetaKeys<dynamicObj>>
    isError ?: boolean
    errorMessage ?: string
    readonly ?: boolean
    disabled ?: boolean
    translationKey ?: string
    afterClick?: () => void
    innerHtml?: any
  }
  const supplierLayoutStore = useSupplierLayoutsStore();
  const { formLayout , formConfigure } = storeToRefs(supplierLayoutStore);
  
  const props = withDefaults(
    defineProps<FieldProps>(),
    {
      translationKey: 'supplier_register_form'
    });

  const emit = defineEmits(['update:modelValue']);
   
  const { meta_field,afterClick,innerHtml } = props;
  const fieldMetaData = ref([]);
  
  // const wrapperClass = meta_field.class + ' ' + extraClass;
  // add default value
  const onUpdateValue = (event: Event) => {
    emit('update:modelValue', event, meta_field.field_name);
  }
  const asterisk = computed(()=> {
    return props.meta_field.is_required ? '*' : '';
  })
  //conditionally choose the component to render
  const fieldComponent = computed(() => {
    if(['STRING', 'NUMBER', 'TEXTAREA','text', 'number', 'password', 'email', 'tel', 'textarea'].includes(meta_field.field_type)) return InputField as Component
    else if(['radio', 'group-checkbox', 'toggle'].includes(meta_field.field_type)) return OptionField as Component
    else if(['SELECT', 'SEARCH','select', 'search'].includes(meta_field.field_type)) return SelectField as Component
    else if(['FILE', 'file',].includes(meta_field.field_type)) return FileField as Component
    else if(['checkbox', 'BOOLEAN',].includes(meta_field.field_type)) return CheckboxField as Component
    else return null
  });
  
  </script>