<template>
  <div class="saved-filter-badge row absolute">
    <template v-for="[key, value] in quickFilterMap" :key="key">
      <!-- Ignore 'all_invoices' filter and the 'status' key -->
      <template
        v-if="
          value &&
          value.hasOwnProperty('value') &&
          value.value === 'all_invoices'
        "
      >
        <!-- Skip rendering for 'all_invoices' and 'status' -->
        <div>{{ debug() }}</div>
      </template>

      <!-- Render supplier group and status list filters -->
      <template v-else-if="key == 'supplier_group'">
        <q-badge rounded color="primary" class="q-mr-sm capitalize">
          <template v-slot>
            {{ $t(value.value) }}
            <q-icon
              name="close"
              color="white"
              size="xs"
              class="q-ml-xs cursor-pointer"
              style="font-size: 12px !important"
              @click="removeFilter(key)"
            />
          </template>
        </q-badge>
      </template>

      <!-- Handle 'status_list' filter specially -->
      <template v-else-if="key == 'status'">
        <q-badge rounded color="primary" class="q-mr-sm capitalize">
          <template v-slot>
            {{ $t(value.value) }}
            <q-icon
              name="close"
              color="white"
              size="xs"
              class="q-ml-xs cursor-pointer"
              style="font-size: 12px !important"
              @click="removeFilter(key)"
            />
          </template>
        </q-badge>
      </template>

      <!-- Render other filters like 'date_added' or other labels -->
      <q-badge rounded color="primary" class="q-mr-sm" v-else>
        <template v-if="value.hasOwnProperty('label')">
          {{ value.translation_key ? getDocTypeLabel(value) : $t(value.value) }}
        </template>
        <template v-else-if="key == 'restart_filter'">
          {{ $t('restart_required') }}
        </template>
        <template v-else>
          {{ value }}
        </template>
        <q-icon
          name="close"
          color="white"
          class="q-ml-xs cursor-pointer"
          size="xs"
          style="font-size: 12px !important"
          @click="removeFilter(key)"
        />
      </q-badge>
    </template>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import docTypeLable from 'src/utils/docTypeLable';
import { useDashboardSupplierStore } from 'src/supplier/store';

export default defineComponent({
  mixins: [docTypeLable],
  mounted() {
    this.init();
    document.addEventListener(
      'load_saved_filter_badge',
      this.loadSavedFiltersBadges,
    );
  },
  unmounted() {
    document.removeEventListener(
      'load_saved_filter_badge',
      this.loadSavedFiltersBadges,
    );
  },
  methods: {
    async init() {
      await this.$nextTick();
      this.loadSavedFiltersBadges();
    },
    debug() {
      console.log('quickFilterMap', this.quickFilterMap);
    },
    // Function to remove selected filter
    removeFilter(key: string, index?: number, status: any = null) {
      if (key.includes('status_')) {
        // If it's a status filter, remove the status from the status_list
        this.quickFilterMap.get('status_list').splice(index, 1);
        const new_string = this.quickFilterMap
          .get('status')
          .replace(status.value + ',', '');
        this.quickFilterMap.set('status', new_string);
      } else {
        this.quickFilterMap.delete(key);
        this.filter[key] = '';
      }
      if (key == 'keyword') {
        // Trigger an event to clear input text
        const event = new CustomEvent('delete_input_text', { detail: {} });
        document.dispatchEvent(event);
      }

      this.getSupplierData();

      // this.triggerApplyFilters();
      // this.triggerRemoveFilterByKey(key);
    },

    // Trigger the event to apply filters
    // triggerApplyFilters() {
    //   const event = new CustomEvent('apply_filters', { detail: {} });
    //   document.dispatchEvent(event);
    // },

    // Trigger the event to remove filter by key
    // async triggerRemoveFilterByKey(key: string) {
    //   await this.$nextTick();
    //   const remove_filters_event = new CustomEvent('remove_filter_by_key', { detail: key });
    //   document.dispatchEvent(remove_filters_event);
    // },

    // Adjust the position of the saved filter badges based on the search input field's position
    loadSavedFiltersBadges() {
      const search_input_el = document.querySelector(
        '.search-input',
      ) as HTMLDivElement;
      if (!search_input_el) {
        return;
      }

      const saved_filter_badge_el = document.querySelector(
        '.saved-filter-badge',
      ) as HTMLDivElement;
      if (!saved_filter_badge_el) {
        return;
      }
      let rect = search_input_el.getBoundingClientRect();
      let left = Number(rect.left + window.pageXOffset);
      saved_filter_badge_el.style.left = left - 20 + 'px';
    },
  },
  setup() {
    const dashboard_store = useDashboardSupplierStore();
    const { quickFilterMap, filter } = storeToRefs(dashboard_store);
    const { getSupplierData } = dashboard_store;

    return {
      filter,
      quickFilterMap,
      getSupplierData,
    };
  },
});
</script>
