<template>
  <div class="row q-mb-md">
    <div
      style="margin-top: 39px"
      class="row items-start example-container dashboard-title dark-readable"
    >
      <div
        class="example-cell cursor-pointer"
        tabindex="0"
        @click="getAllSupplier"
      >
        {{ $t('all_suppliers') }} ({{ total_supplier_count }})
      </div>
      <div
        class="example-cell q-ml-lg cursor-pointer"
        tabindex="0"
        @click="getPendingSupplier"
      >
        {{ $t('pending_approval') }} ({{ pending_approval_supplier }})
      </div>
      <div
        class="example-cell q-ml-lg cursor-pointer"
        tabindex="0"
        @click="getPendingRegitationSupplier"
      >
        {{ $t('pending_registration') }} ({{ pending_registration_supplier }})
      </div>
    </div>
    <div class="col q-ml-xl">
      <div class="row justify-start">
        <div class="dashboard-search-box q-ml-md mt-20 white-inputs">
          <quickSearch />
        </div>
        <q-space />
        <f-btn
          square
          class="q-mr-sm mt-20"
          @click="refreshFilters"
        >
          <Icon icon="mdi:refresh" width="20" height="20" />
          <q-tooltip>{{ $t('refresh_list') }}</q-tooltip>
        </f-btn>
        <f-btn
          square
          class="q-mr-sm mt-20"
          @click="openColumnSettings"
        >
          <Icon icon="mdi:filter-variant" width="20" height="20" />
          <q-tooltip>{{ $t('table_column_settings_tooltip') }}</q-tooltip>
        </f-btn>
        <ColumnSettings
          ref="columnSettingsRef"
          :columns="allColumns"
          :visible-column-objects="visibleColumns"
          :show-trigger-button="false"
          label-key="translation_key"
          :enable-batch-selection="true"
          @open="onColumnSettingsOpen"
          @save="onColumnSettingsSave"
          @cancel="onColumnSettingsCancel"
        />
        <f-btn
          square
          class="q-mr-sm mt-20"
          @click="show_analytics = !show_analytics"
        >
          <Icon icon="mdi:chart-bar" width="20" height="20" />
          <q-tooltip>{{ $t('analytics') }}</q-tooltip>
        </f-btn>
        <f-btn
          square
          color="primary"
          class="q-mr-sm mt-20 add-icon"
          icon="add"
          @click="created_dialog = !created_dialog"
        >
          <q-tooltip>{{ $t('create_supplier') }}</q-tooltip>
        </f-btn>
        <q-dialog v-model="created_dialog" persistent>
          <SupplierCreate />
        </q-dialog>
      </div>
    </div>
  </div>
  <div
    class="row mb-25 relative-position"
    style="margin-bottom: 8px"
    v-if="quickFilterMap.size > 0"
  >
    <div class="dashboard-toggler-area"></div>
    <savedFilterBadges />
  </div>

  <template v-if="show_analytics">
    <q-separator class="q-mb-md" />
    <analytics />
    <div class="q-mb-md" />
  </template>
</template>

<script lang="ts">

import { ref, defineComponent, PropType } from 'vue';
import { storeToRefs } from 'pinia';
import analytics from './analytics.vue';
import quickSearch from './filter/quick-search.vue';
import { supplier_dashboard_columns } from 'src/constants';
import { useDashboardSupplierStore } from '../../store/index';
import { useSettingStore } from 'src/store/Settings/setting.store';
import SupplierCreate from 'src/supplier/components/SupplierCreate.vue';
import { ColumnSettings } from 'src/components/Table';
import type { ColumnSettingsSavePayload, ColumnSettingsExposed } from 'src/components/Table';
import savedFilterBadges from 'src/supplier/components/dashboard/saved-filter-badges.vue';

export default defineComponent({
  name: 'DashboardHeader',
  components: {
    
    analytics,
    quickSearch,
    SupplierCreate,
    ColumnSettings,
    savedFilterBadges,
  },
  props: {
    type_name: {
      type: String as PropType<string>,
      default: undefined,
    },
    additionalFields: {
      type: Array as PropType<any[]>,
      default: () => [],
    },
  },
  setup() {
    const supplierStore = useDashboardSupplierStore();
    const settingsStore = useSettingStore();

    const {
      quickFilterMap,
      current_supplier,
      pending_approval_supplier,
      pending_registration_supplier,
      total_supplier_count,
      filter,
      created_dialog,
      table_columns,
    } = storeToRefs(supplierStore);

    const {
      resetFilter,
      getSupplierData,
      resetPagination,
      getSavedColumns,
    } = supplierStore;

    const { updateSetting } = settingsStore;

    return {
      // Store refs
      quickFilterMap,
      current_supplier,
      pending_approval_supplier,
      pending_registration_supplier,
      total_supplier_count,
      filter,
      created_dialog,
      table_columns,
      // Store methods
      resetFilter,
      getSupplierData,
      resetPagination,
      getSavedColumns,
      updateSetting,
      // Component refs
      columnSettingsRef: ref<ColumnSettingsExposed | null>(null),
      // State
      show_analytics: ref(false),
      searchInput: ref(''),
      visibleColumns: ref<Record<string, any>>({}),
    };
  },
  computed: {
    /**
     * All available columns mapped to ColumnSettings format
     */
    allColumns(): any[] {
      return Object.values(this.table_columns).map((col: any) => ({
        name: col.field || col.name,
        label: col.translation_key,
        translation_key: col.translation_key,
        field: col.field || col.name,
        actions: col.actions,
        order: col.order,
        visible: true,
      }));
    },
  },
  async mounted() {
    document.addEventListener('delete_input_text', this.clearSearchInput);
    await this.loadVisibleColumns();
  },
  beforeUnmount() {
    document.removeEventListener('delete_input_text', this.clearSearchInput);
  },
  methods: {
    /**
     * Load saved columns into the record shape ColumnSettings expects.
     * Supplier store returns an array — adapt it once, here, at the boundary.
     */
    async loadVisibleColumns() {
      try {
        const savedColumns = await this.getSavedColumns();
        this.visibleColumns = savedColumns && savedColumns.length > 0
          ? this.toVisibleRecord(savedColumns)
          : { ...this.table_columns };
      } catch (err) {
        logError('Failed to load saved columns:', err);
        this.visibleColumns = { ...this.table_columns };
      }
    },
    toVisibleRecord(cols: any[]): Record<string, any> {
      return [...cols]
        .sort((a, b) => (a.order ?? 0) - (b.order ?? 0))
        .reduce((acc: Record<string, any>, col) => {
          acc[col.field || col.name] = col;
          return acc;
        }, {});
    },
    /**
     * Load saved column settings when dialog opens
     */
    async onColumnSettingsOpen() {
      await this.loadVisibleColumns();
    },
    /**
     * Save column settings when user clicks Done
     */
    async onColumnSettingsSave(payload: ColumnSettingsSavePayload) {
      try {
        // Map to the format the supplier setting expects (record keyed by name)
        const columnsToSave: Record<string, any> = {};
        payload.visibleColumns.forEach((col, index) => {
          columnsToSave[col.name] = {
            name: col.name,
            label: col.label,
            order: index,
            sortable: col.sortable ?? false,
            translation_key: col.translation_key || col.name,
            field: col.name,
          };
        });

        await this.updateSetting(supplier_dashboard_columns, JSON.stringify(columnsToSave));

        // Close the dialog
        this.columnSettingsRef?.close();

        // Dispatch event to notify table of column changes
        const event = new CustomEvent('columnsUpdated', {
          detail: {
            visible_columns: payload.visibleColumns.map((col, index) => ({
              name: col.name,
              field: col.name,
              label: col.label,
              translation_key: col.translation_key || col.name,
              order: index,
              actions: col.actions ?? true,
            })),
          },
        });
        document.dispatchEvent(event);
      } catch (err) {
        logError('Failed to save column settings:', err);
        this.columnSettingsRef?.setSaving(false);
      }
    },
    /**
     * Handle cancel - just close the dialog
     */
    onColumnSettingsCancel() {
      // Nothing special needed, dialog handles closing
    },
    /**
     * Open the column settings dialog
     */
    openColumnSettings() {
      this.columnSettingsRef?.open();
    },
    /**
     * Refresh filters and reload data
     */
    refreshFilters() {
      this.filter.insurance_expired = 0;
      this.getSupplierData();
    },
    /**
     * Get all suppliers (clear filters)
     */
    getAllSupplier() {
      this.resetFilter();
      this.getSupplierData();
    },
    /**
     * Filter by pending approval status
     */
    async getPendingSupplier() {
      this.resetPagination();
      const count = this.current_supplier;
      this.filter.status = {
        label: 'Pending Approval',
        value: 'pending_approval',
      } as any;

      await this.getSupplierData();
      this.current_supplier = count;
    },
    /**
     * Filter by pending registration status
     */
    async getPendingRegitationSupplier() {
      this.resetPagination();
      const count = this.current_supplier;
      this.filter.status = {
        label: 'Pending Registration',
        value: 'pending_registration',
      } as any;

      await this.getSupplierData();
      this.current_supplier = count;
    },
    /**
     * Clear search input
     */
    clearSearchInput() {
      this.searchInput = '';
    },
  },
});
</script>

<style scoped lang="scss">
:deep(.add-icon i) {
  font-size: 1.84rem;
}
.p-4-8 {
  padding: 4px 8px;
}
.search-invoices {
  width: 500px;
  padding: 0;
  transition: 0.3s;
}
</style>
