<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { removeSortOrderFromStorage } from 'src/utils/ms_utlis';
import { useDashboardSupplierStore } from 'src/supplier/store/index';
import GroupFilter from 'src/supplier/components/dashboard/filter/group-filter.vue';
import DateAdded from 'src/supplier/components/dashboard/filter/date_added-filter.vue';
import StatusFilter from 'src/supplier/components/dashboard/filter/supplier_status-filter.vue';

export default defineComponent({
  mixins: [],
  props: {},
  components: {
    StatusFilter,
    GroupFilter,
    DateAdded,
    // ZipCode,
    // ComplianceStatus,
    // PerformanceFilter,
    // OrderFrequency,
    // PaymentTermFilter,
    // LastOrderDateFilter,
    // SustainabiltityRatingFilter
  },
  methods: {
    resetFilters() {
      this.removeSortOrderFromStorage('supplier');
      this.resetFilter();
      this.getSupplierData();
    },

    loadSavedFiler() {
      const keyword = this.quickFilterMap.get('keyword');
      if (!keyword) {
        return;
      }

      this.searchInput = keyword;
    },

    onKeyup(event: any) {
      if (event.key == 'Enter') {
        this.fetchData();
      }
    },
    async fetchData() {
      if (this.filter.search) {
        this.filter.search = this.filter.search.trim();
      } else {
        this.quickFilterMap.delete('keyword');
      }

      this.resetPagination();
      await this.getSupplierData();
    },

    handleEmptyStatus() {
      if (
        !(
          !this.searchInput ||
          this.searchInput === null ||
          this.searchInput.trim() === ''
        )
      ) {
        return false;
      }

      this.resetFilters();
      return true;
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },
    validatePaginationSize() {
      if (this.pagination.page_size <= 50) return;
      this.pagination.page_size = 50;
    },
  },

  mounted() {
    this.validatePaginationSize();
  },
  setup() {
    const dashboard_store = useDashboardSupplierStore();
    const pagination_options = ['10', '20', '25', '50'];
    const { quickFilterMap, loading, pagination, filter } =
      storeToRefs(dashboard_store);
    const { getSupplierData, resetPagination, resetFilter } = dashboard_store;

    return {
      getSupplierData,
      resetFilter,
      pagination,
      filter,
      loading,
      searchInput: ref(''),
      oldSearchInput: ref(''),
      quickFilterMap,
      showing: ref(false),
      debounceSearchInputFunc: {} as any,
      request_params: {} as dynamicObj,
      filter_data_json_str: '',
      pagination_options,
      removeSortOrderFromStorage,
      resetPagination,
    };
  },
});
</script>
