<template>
  <!-- list all expire status -->
  <div class="row items-stretch justify-start">
    <q-card
      v-for="(data, idx) in ExpireStatus"
      :key="idx"
      class="analytic-card cursor-pointer clickable"
      @click="filterTabSelected(data.ref, data.title, data.insurance_expired)"
      :style="{ borderLeftColor: data.color }"
      :class="selected_filter_status === data.ref ? 'selected-card' : ''"
    >
      <q-card-section>
        <div class="text-h6">
          {{ data.title }} ({{ expiredCount?.[data.ref] ?? 0 }})
        </div>
        <div class="text-subtitle2">{{ data.desc }}</div>
      </q-card-section>
      <q-tooltip>{{ data.tip }}</q-tooltip>
    </q-card>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useDashboardSupplierStore } from '../../store/index';
import { storeToRefs } from 'pinia';
import { useTranslate } from '@tolgee/vue';

export default defineComponent({
  mixins: [],
  props: {},
  watch: {
    quickFilterMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadFilters();
      },
    },
  },
  components: {},

  methods: {
    loadFilters() {
      const tab_status = this.quickFilterMap.get('tab_status');
      if (!tab_status) {
        this.selected_filter_status = 'expires_in_1_months';
      }
    },

    filterTabSelected(status: string, label: string, type: number) {
      this.selected_filter_status = status;

      const event = new CustomEvent('quick_filter_remove', {
        detail: 'status',
      });
      document.dispatchEvent(event);

      this.quickFilterMap.set('tab_status', {
        value: status,
        label: label,
      });
      this.triggerApplyFilters();
      this.getExpiredSupplier(type);
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },
    async getExpiredSupplier(type: number) {
      this.resetPagination();
      logInfo(type);

      const count = { ...{ count: this.current_supplier } };
      this.filter = {
        insurance_expired: Number(type),
      } as any;

      await this.getSupplierData();
      this.current_supplier = count.count;
    },
  },
  setup() {
    const { t } = useTranslate();
    //=== Expire Status Data ==//
    const ExpireStatus = ref<
      Array<{
        id: number;
        title: any;
        desc: string;
        tip: string;
        ref: string;
        color: string;
        insurance_expired: number;
      }>
    >([
      {
        id: 1,
        title: t.value('expired'),
        desc: '',
        tip: `${t.value('expired')}`,
        ref: 'expired',
        color: '#FF0000',
        insurance_expired: -1,
      },
      {
        id: 2,
        title: t.value('expires_in'),
        desc: `1 ${t.value('month')}`,
        tip: `${t.value('expires_in')} 1${t.value('month')}`,
        ref: 'expired_in_1_month',
        color: '#2388ae',
        insurance_expired: 1,
      },
      {
        id: 3,
        title: t.value('expires_in'),
        desc: `2 ${t.value('month')}`,
        tip: `${t.value('expires_in')} 2${t.value('month')}`,
        ref: 'expired_in_2_months',
        color: '#409fff',
        insurance_expired: 2,
      },
      {
        id: 4,
        title: t.value('expires_in'),
        desc: `3 ${t.value('month')}`,
        tip: `${t.value('expires_in')} 3${t.value('month')}`,
        ref: 'expired_in_3_months',
        color: '#ffe240',
        insurance_expired: 3,
      },
      {
        id: 5,
        title: t.value('expires_in'),
        desc: `6 ${t.value('month')}`,
        tip: `${t.value('expires_in')} 6${t.value('month')}`,
        ref: 'expired_in_6_months',
        color: '#41b2bb',
        insurance_expired: 6,
      },
      {
        id: 6,
        title: t.value('expires_in'),
        desc: `1 ${t.value('year')}`,
        tip: `${t.value('expires_in')} 1${t.value('year')}`,
        ref: 'expired_in_1_year',
        color: '#80bb41',
        insurance_expired: 12,
      },
    ]);
    const dashboard_supplier_store = useDashboardSupplierStore();
    const {
      current_supplier,
      pending_approval_supplier,
      display_data,
      loading,
      paginationCount,
      quickFilterMap,
      table_columns,
      supplier_status,
      sortby_data_types,
      created_dialog,
      pagination,
      expiredCount,
      filter,
    } = storeToRefs(dashboard_supplier_store);
    const {
      resetFilter,
      getSupplierData,
      getColumnPreference,
      resetPagination,
    } = dashboard_supplier_store;
    return {
      show_analytics: ref(false),
      selected_filter_status: ref(''),
      current_supplier,
      pending_approval_supplier,
      display_data,
      loading,
      paginationCount,
      quickFilterMap,
      table_columns,
      supplier_status,
      sortby_data_types,
      created_dialog,
      pagination,
      ExpireStatus,
      expiredCount,
      filter,
      resetFilter,
      getSupplierData,
      getColumnPreference,
      resetPagination,
      t,
    };
  },
});
</script>
<style lang="scss" scoped>
.analytic-card {
  margin-right: 20px;
  border-left-width: 5px;
  border-left-style: solid;
  min-width: 200px;
  width: auto;
  text-align: center;
  margin-bottom: 5px;
}
.selected-card {
  background: #b5dfe587;
}
</style>
